sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // gs.info('WRM State Sync BR fired for reservation: ' + current.number);
    // Ensure reservation status exists
    if (!current.reservation_status) {
        return;
    }

    var newState = '';

    switch (current.reservation_status.toString()) {

        case 'checked_in':
            newState = '1'; // Open
            break;

        case 'no_show':
        case 'cancelled':
            newState = '7'; // Closed Skipped
            break;

        case 'checked_out':
            newState = '3'; // Closed Complete
            break;

        default:
            // No state change needed for other statuses
            return;
    }

    // Load the underlying task record
    var task = new GlideRecord('task');
    if (!task.get(current.sys_id)) {
        // gs.info('WRM State Sync: Task record not found for sys_id ' + current.sys_id);
        return;
    }

    // Only update if needed
    if (task.state != newState) {
        gs.info('WRM State Sync: Updating task.state from ' + task.state + ' to ' + newState);
        // task.setWorkflow(false); // This causes cross-scope error
        task.setValue('state', newState);
        task.update();        
    }

})(current, previous);
